// Resolve the roles of source metadata before drawing any carrier. The source
// itself stays untouched, including older snapshots with retrieval tags in parts.
const comparison=value=>String(value||'').normalize('NFKC').toLocaleLowerCase().replace(/[\s\p{P}\p{S}]+/gu,'');
export function exhibitionSourcePresentation({title='',page='',source=null,texts=[],narrative=[]}={}) {
  const same=(a,b)=>Boolean(comparison(a))&&comparison(a)===comparison(b);
  const interactive=source?.rich || ['interactive','embed'].includes(source?.view_kind);
  const eyebrow=same(page,title)?(interactive?'Interactive work':''):page;
  const tags=Array.isArray(source?.topics)?source.topics.join(', '):'';
  const paragraphs=(texts.length?texts:narrative).filter(text=>String(text||'').trim()).filter(text=>!(interactive&&tags&&same(text,tags)));
  // Only standalone heading text at the beginning is redundant. A paragraph
  // that develops or quotes the title keeps its full wording.
  while(paragraphs.length&&(same(paragraphs[0],title)||same(paragraphs[0],eyebrow)))paragraphs.shift();
  return {title,eyebrow,paragraphs};
}
